-- Versioned MCS Prelims paper roles; canonical question tags/keys are unchanged.
BEGIN;
DO $$ BEGIN
 IF (SELECT live_version FROM collections WHERE id='combined-prelims')<>1 THEN
  RAISE EXCEPTION 'MCS predecessor changed: reconcile before publishing version 2';
 END IF;
END $$;
INSERT INTO collection_papers(collection_id,version,paper_id,as_mock,section_path,display_title,duration_minutes,marks_correct,marks_wrong,instructions,allow_browse,allow_practice,rule_source)
SELECT cp.collection_id,2,cp.paper_id,cp.as_mock,CASE WHEN p.paper_number='I' THEN 'gs' ELSE 'aptitude' END,
 cp.display_title,cp.duration_minutes,cp.marks_correct,cp.marks_wrong,cp.instructions,cp.allow_browse,cp.allow_practice,cp.rule_source
 FROM collection_papers cp JOIN papers p ON p.id=cp.paper_id WHERE cp.collection_id='combined-prelims' AND cp.version=1;
INSERT INTO collection_papers(collection_id,version,paper_id,as_mock,section_path,display_title,marks_correct,marks_wrong,instructions,allow_browse,allow_practice,rule_source)
SELECT 'combined-prelims',2,id,false,CASE WHEN paper_number='I' THEN 'gs' ELSE 'aptitude' END,
 paper_subject||' · '||year::text,1,0,'Recovered Chase Academy reproduction. Searchable extraction and booklet identity need final source review. No answer key has been attached. Read passages, formulas and figures in the source image/PDF.',true,false,'platform-default'
 FROM papers WHERE id IN ('Old_Questions/Recovered_MCS/MCS Combined 2015 Preliminary Exam Paper-I Series-A Chase copy.pdf','Old_Questions/Recovered_MCS/MCS Combined 2015 Preliminary Exam Paper-II Series-A Chase copy.pdf','Old_Questions/Recovered_MCS/MCS Combined 2017 Preliminary Exam Paper-I Series-A Chase copy.pdf','Old_Questions/Recovered_MCS/MCS Combined 2017 Preliminary Exam Paper-II Series-A Chase copy.pdf','Old_Questions/Recovered_MCS/MCS Combined 2018 Preliminary Exam Paper-I Series-A Chase copy.pdf','Old_Questions/Recovered_MCS/MCS Combined 2018 Preliminary Exam Paper-II Series-A Chase copy.pdf')
ON CONFLICT(collection_id,version,paper_id) DO UPDATE SET as_mock=false,allow_practice=false,instructions=excluded.instructions;
INSERT INTO collection_sections(collection_id,version,path,title,position,query)
SELECT 'combined-prelims',2,role.path,role.title,role.position,
 jsonb_build_object('paper_ids',COALESCE(jsonb_agg(cp.paper_id ORDER BY cp.paper_id) FILTER(WHERE cp.paper_id IS NOT NULL),'[]'::jsonb))
 FROM (VALUES ('gs','Paper I · General Studies',0),('aptitude','Paper II · Aptitude Tests',1))role(path,title,position)
 LEFT JOIN collection_papers cp ON cp.collection_id='combined-prelims' AND cp.version=2 AND cp.section_path=role.path GROUP BY role.path,role.title,role.position;
UPDATE collections SET live_version=2,updated_at=now() WHERE id='combined-prelims';
INSERT INTO review_documents(id,paper_id,title,source_file,sha256,kind,registered_by) SELECT 'mcs-recovered-2015-i',id,'Recovered MCS 2015 Paper I — Chase Academy copy','pdfs/Old_Questions/Recovered_MCS/MCS Combined 2015 Preliminary Exam Paper-I Series-A Chase copy.pdf','d8ed118b1965298a51ec597f09e0c5613683708c6c2a2945d28813e1862c7cbe','paper','operator:mcs-source-import-20261031' FROM papers WHERE id='Old_Questions/Recovered_MCS/MCS Combined 2015 Preliminary Exam Paper-I Series-A Chase copy.pdf' ON CONFLICT(id) DO NOTHING;
