INSERT INTO bank_inventory_events(actor_id,action,target_id,after_data,reason) VALUES('operator:mcs-source-import-20261031','mcs_paper_roles_published','combined-prelims',jsonb_build_object('version',2,'recovered_papers',6,'source_records',600,'answers_added',0),'Owner requested recovered historical MCS papers and separate GS/Aptitude study. Reproductions remain provisional; no official keys or complete simulation certified.');
